import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]
    B = [int(next(it)) for _ in range(N)]

    max_fixed_A = -1          # maximum among fixed A_i (non‑negative)
    max_fixed_B = -1          # maximum among fixed B_i (non‑negative)
    both_fixed_sum = None     # sum of a pair where both entries are fixed
    possible = True

    for i in range(N):
        a = A[i]
        b = B[i]
        if a != -1:
            if a > max_fixed_A:
                max_fixed_A = a
        if b != -1:
            if b > max_fixed_B:
                max_fixed_B = b
        if a != -1 and b != -1:
            s = a + b
            if both_fixed_sum is None:
                both_fixed_sum = s
            elif both_fixed_sum != s:
                possible = False

    if not possible:
        print("No")
        return

    if both_fixed_sum is not None:
        C = both_fixed_sum
        # every fixed value must not exceed C
        if max_fixed_A > C or max_fixed_B > C:
            print("No")
        else:
            print("Yes")
    else:
        # no pair is fixed on both sides, we can always choose a large enough C
        print("Yes")

if __name__ == "__main__":
    solve()

