class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        # not enough strings after removing one element
        if n <= k:
            return [0] * n

        # ---------- Trie ----------
        class Node:
            __slots__ = ('children', 'depth', 'cnt')
            def __init__(self, depth: int):
                self.children = {}
                self.depth = depth
                self.cnt = 0

        root = Node(0)
        all_nodes = [root]                     # for later traversals

        for w in words:
            node = root
            for ch in w:
                if ch not in node.children:
                    child = Node(node.depth + 1)
                    node.children[ch] = child
                    all_nodes.append(child)
                node = node.children[ch]
                node.cnt += 1                  # every word passes this node

        # ---------- compute D1 and G[d] ----------
        D1 = 0                                 # deepest node with cnt >= k+1
        max_depth = 0
        G = {}                                 # depth -> number of type‑B nodes
        for nd in all_nodes:
            d = nd.depth
            if d > max_depth:
                max_depth = d
            if nd.cnt >= k + 1:
                if d > D1:
                    D1 = d
            if nd.cnt == k:                    # type‑B node
                G[d] = G.get(d, 0) + 1

        # ---------- segment tree for A[d] ----------
        size = 1
        while size <= max_depth:
            size <<= 1
        seg = [0] * (2 * size)

        # initialise leaves
        for d in range(max_depth + 1):
            seg[size + d] = G.get(d, 0)
        # build internal nodes (max)
        for i in range(size - 1, 0, -1):
            seg[i] = seg[i << 1] if seg[i << 1] > seg[i << 1 | 1] else seg[i << 1 | 1]

        # helpers
        def seg_update(pos: int, delta: int) -> None:
            i = pos + size
            seg[i] += delta
            i >>= 1
            while i:
                left = seg[i << 1]
                right = seg[i << 1 | 1]
                seg[i] = left if left > right else right
                i >>= 1

        def seg_query_rightmost() -> int:
            if seg[1] <= 0:
                return -1
            i = 1
            while i < size:
                # go to the right child if it still has a positive value
                if seg[i << 1 | 1] > 0:
                    i = i << 1 | 1
                else:
                    i = i << 1
            return i - size

        # ---------- answer each word ----------
        ans = [0] * n
        for idx, w in enumerate(words):
            node = root
            rev = []               # depths of type‑B nodes on this path
            for ch in w:
                node = node.children[ch]
                if node.cnt == k:
                    d = node.depth
                    seg_update(d, -1)
                    rev.append(d)

            d2 = seg_query_rightmost()
            best = D1
            if d2 != -1 and d2 > best:
                best = d2
            ans[idx] = best

            # restore the tree
            for d in rev:
                seg_update(d, +1)

        return ans

