import sys

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)
        if k > n:
            return 0

        xs = [p[0] for p in points]
        ys = [p[1] for p in points]

        lo, hi = 0, 2 * side

        # test whether we can pick k points with pairwise Manhattan distance >= D
        def can(D: int) -> bool:
            # any two distinct points have Manhattan distance at least 1
            if D <= 1:
                return True

            # Greedy attempt – fast for dense feasible cases
            selected = []
            for idx in range(n):
                if len(selected) == k:
                    break
                x, y = xs[idx], ys[idx]
                ok = True
                for s in selected:
                    if abs(x - xs[s]) + abs(y - ys[s]) < D:
                        ok = False
                        break
                if ok:
                    selected.append(idx)
            if len(selected) == k:
                return True

            # Backtracking (branch & bound) to find a k‑clique in the graph
            # where edges connect points with distance >= D.
            sys.setrecursionlimit(10000)
            cand = list(range(n))

            def dfs(depth: int, cand: List[int]) -> bool:
                if depth == k:
                    return True
                if len(cand) < k - depth:
                    return False

                # Build neighbour lists for each candidate and sort by degree
                # (low degree first) – a classic heuristic for max‑clique search.
                nbrs = []
                for i, p in enumerate(cand):
                    x1, y1 = xs[p], ys[p]
                    nb = []
                    for q in cand[i + 1:]:
                        if abs(x1 - xs[q]) + abs(y1 - ys[q]) >= D:
                            nb.append(q)
                    nbrs.append((p, nb))
                nbrs.sort(key=lambda item: len(item[1]))

                for p, nb in nbrs:
                    # Even if all remaining compatible points are taken we cannot reach k
                    if len(nb) < k - depth - 1:
                        continue
                    if dfs(depth + 1, nb):
                        return True
                return False

            return dfs(0, cand)

        # binary search on the answer
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

