class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Numbers larger than the threshold can never be connected to any other node.
        big = 0
        small = []
        for v in nums:
            if v > threshold:
                big += 1
            else:
                small.append(v)

        k = len(small)
        if k == 0:
            return big

        # Disjoint Set Union (DSU) for the numbers that are <= threshold.
        parent = list(range(k))
        size = [1] * k

        def find(x: int) -> int:
            # Iterative path compression
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x: int, y: int) -> None:
            xr = find(x)
            yr = find(y)
            if xr == yr:
                return
            if size[xr] < size[yr]:
                xr, yr = yr, xr
            parent[yr] = xr
            size[xr] += size[yr]

        # For each multiple up to threshold we remember the first small number that reaches it.
        # If another number also reaches the same multiple we union the two numbers.
        first = [-1] * (threshold + 1)  # stores index in the `small` list
        for idx, val in enumerate(small):
            # iterate over all multiples of val not exceeding threshold
            for m in range(val, threshold + 1, val):
                if first[m] == -1:
                    first[m] = idx
                else:
                    union(idx, first[m])

        # Count distinct DSU roots among the small numbers.
        roots = set()
        for i in range(k):
            roots.add(find(i))

        return len(roots) + big
